WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') so_ct,coalesce(%s::text,'') ma_vt,coalesce(%s::text,'') ma_dvcs,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY h.ngay_ct DESC,h.so_ct,c.ln) stt,h.stt_rec,h.ma_dvcs,h.ma_ct,h.ma_gd,h.ngay_ct,h.so_ct,h.ma_ncc,h.ma_vt,v.ten_vt,h.ma_lo,h.dvt,h.so_luong,h.so_luong_mau,h.so_luong_ok,h.so_luong_ng,h.ma_nv,h.bai_kiem_tra,h.ket_qua,h.dien_giai,c.ln,c.ma_chi_tieu,t.ten_chi_tieu,c.gia_tri,c.ket_qua chi_tiet_ket_qua,c.kq_danh_gia,c.ghi_chu,h.status,count(*) OVER() total FROM public.phiqc h LEFT JOIN public.ctiqc c ON c.stt_rec=h.stt_rec LEFT JOIN public.dmvt v ON v.ma_vt=h.ma_vt LEFT JOIN public.qcdmchitieu t ON t.ma_chi_tieu=c.ma_chi_tieu CROSS JOIN s WHERE s.ok IS NOT NULL AND h.ngay_ct BETWEEN s.d1 AND s.d2 AND (s.so_ct='' OR h.so_ct ILIKE '%%'||s.so_ct||'%%') AND (s.ma_vt='' OR h.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.ma_dvcs='' OR h.ma_dvcs=ANY(string_to_array(s.ma_dvcs,','))) AND (s.unrestricted OR h.ma_dvcs=ANY(string_to_array(s.bs,','))) ORDER BY h.ngay_ct DESC,h.so_ct,c.ln LIMIT (SELECT lim FROM p);
